('386e6570-b2c3-4a88-b635-1e8c5778595c','{"val_partido":"SIN VER","valoracion":"4.INTERESANTE","car_obs_PUNTA":"ES UN CHICO QUE HA VENIDO PERDIENDO ESPACIO, SUFRIO UNA LESION ANTES DEL MUNDIAL DE LA CUAL AUN NO REGRESA."}'),
('39d2fb43-670b-4b74-b4f4-28710810e766','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"4.INTERESANTE","car_obs_CENTRAL":"CANTERANO DE LIGA DE QUITO, TUVO UN PASO PREVIO POR EL FUTBOL DE COSTA RICA. SE ESTA ADAPTANDO A LA PRIMERA DE ESTADOS UNIDOS."}'),
