('3bd40e93-532a-4af6-a14f-9846761af2c9','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_MEDIOCENTRO":"Bastante acertado en el pase, toma buenas decisiones y mueve el equipo de lado a lado. Buena técnica y visión de juego"}'),
