('86e9557b-4030-4358-b16c-2c353d656426','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"2.DESCARTAR","car_obs_EXTREMO":"ES UN EXTREMO QUE SE ASOCIA BASTANTE, YO NO CUENTA CON LA VELOCIDAD QUE LO CARACTERIZABA EN EL INICIO DE SU CARRERA. TUVO UN PASO POR ORENSE FRUCTIFERO."}'),
