('7a8c950f-5795-4aa9-b32e-aff30feba8d7','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_CENTRAL":"Central jóven de buena proyección a futuro, muestra buena personalidad para liderar su defensa, posee buen pase inicial, atento a coberturas y tratar de anticipar, todavía debe mejorar su juego aéreo, cumple pero podría ser mejor para imponerse en esos duelos, en velocidad por momentos no muestra tanto sprint a campo abierto, pero hay partidos que se lo ve mejor en esa faceta, hay que seguirlo de cerca y ver cómo evoluciona, perfil interesante para observar."}'),
('7b106388-0bf1-46e8-8a57-e7f6837c38c6','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_EXTREMO":"EXTREMO DE UNA EDAD AVANZADA."}'),
