('9bc3ada5-729c-4875-ad40-10f095c9912d','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"5.FICHAR","car_obs_EXTREMO":"ES UN EXTREMO QUE CUENTA CON GRAN VELOCIDAD, ES DESEQUILIBRANTE EN EL 1VS1, VIENE DEMOSTRANDO QUE NO LE COSTO ADAPTARSE A LA SERIE A."}'),
('9c9af04f-00af-40b0-aa49-dfff35f95337','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"2.DESCARTAR","car_obs_CENTRAL":"NO ES UN MAL ELEMENTO, PERO CONSIDERO QUE NO DESTACA EN SU POSICION."}'),
