('ac5e1425-989c-4f66-b7e0-6dc6fe96254e','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"2.DESCARTAR","car_obs_ARQUERO":"NO SUPERA LO PROPIO, TIENE RENDIMIENTOS ALEATORIOS, NO ES CONSTANTE."}'),
