('af49b8bd-2eba-4efe-9181-0c8e520eca4e','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"2.DESCARTAR","car_obs_ARQUERO":"ES UN PORTERO QUE LE ESTA TOCANDO SER TITULAR ANTE LA LESION DE ORTIZ, NO DESENTONA, PERO NO SUPERA LOS RENDIMIENTOS PROPIOS."}'),
