('f26b02b0-9805-4573-a3fe-d3bbd5923863','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"4.INTERESANTE","car_obs_PUNTA":"ES UN CHICO QUE CUENTA CON MUCHA MOVILIDAD POR TODO EL FRNETE DE ATAQUE, EN LA DINAMICA DE NUESTRO CAMPEONATO ES UN JUGADOR QUE POR SUS CARACTERISTICAS PUEDE SER INTERESANTE."}'),
