('05088783-5489-4a21-89eb-fd4d9e61c704','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"5.FICHAR","car_obs_EXTREMO":"JEFFERSON ES UN EXTREMO DE GRANDES CONDICIONES FISICAS, SE SUELE IMPONER POR VELOCIDAD A LOS DUELOS, CONSTANTE MENTE BUSCA EL ENGANCHE HACIA DENTRO PARA BUSCAR REMATE A PUERTA. JUEGA A PERFIL CAMBIADO."}'),
