('f51c7c1f-993b-49aa-a831-d8138735a347','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"3.SEGUIR VIENDO","car_obs_MEDIOCENTRO":"JEFFERSON ES UN JUGADOR CON RECORRIDO EN VARIOS CLUBES IMPORTANTES A NIVEL LOCAL, TUVO EXPERIENCIAS POR LA LIGA MX, REGRESO ESTE AÑO PARA JUGAR EN BACELONA, ACTUALMENTE ESTA TENIENDO UN RENDIMIENTO DISCRETO. JUGO 64 MINUTOS TERMINO SALIENDO POR UNA LESION, POSTERIORMENTE SE CONFIRMO QUE REQUERIRA UNA INTERVENCION QUIRURGICA."}'),
('f6b3e8d1-653d-4243-a806-9456e8ecec79','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"4.INTERESANTE","car_obs_ARQUERO":"POSIBLE NO RENOVACION EN SU CLUB, SE VIO EXPUESTO EN UN DISCUSION CON ENTRENADOR EN PLENO JUEGO..."}'),
('f6e57469-6ec6-4f26-b92d-fa6b92244bf7','{"val_partido":"5. MUY IMPORTANTE","valoracion":"3.SEGUIR VIENDO","car_obs_ARQUERO":"Fué de la cantera de Orense pero lamentablemente su nivel se ha estancado y no ha logrado repuntar, incluso tuvo complicidad en uno de los goles y por tal motivo fué sustituido, por edad habrá que seguir viendo más adelante pero sin ser para nada prioridad a corto plazo."}'),
('f9451012-38e6-4362-96d6-245020f8ca3c','{"val_partido":"5. MUY IMPORTANTE","valoracion":"2.DESCARTAR","car_obs_CENTRAL":"No mejora lo nuestro. Descarte."}'),
('ff5bb9a2-3c3b-4b3f-a8c9-a8b2ec821a7c','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_MEDIOCENTRO":"BUENA REFERENCIA POSICIONAL, IMP EN EQUILIBRIO, POCO DINAMICO"}'),
('03a3a263-376f-408e-a0e9-eb8bdcfd80be','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"4.INTERESANTE"}'),
