('04e355b9-2128-4365-985e-eeb2b5bbf16f','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"3.SEGUIR VIENDO","car_obs_MEDIAPUNTA":"Volante ofensivo que tiene buen remate de media distancia y suele ser un perfil asociativo de buen pie técnicamente, quizá el contexto actual de su equipo no le ayuda a dar su potencial, por edad es un perfil a tenerlo registrado y seguir observando."}'),
('05f7abcc-8f66-47cb-84e1-cd1130f92b3d','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"2.DESCARTAR"}'),
