('5f379369-caf1-4ce0-9ed4-02e0cc1de813','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"2.DESCARTAR","car_obs_INTERIOR":"Por edad y buscando proyección totalmente descartado."}'),
