('a8669c97-58cd-4453-a760-011d2bfef498','{"val_partido":"SIN VER","valoracion":"4.INTERESANTE","car_obs_EXTREMO":"EXTREMO QUE DESTACA POR SU VELOCIDAD. TRANCOS MUY LARGOS POR LO QUE CUANDO SE PROYECTA AL ESPACIO ES MUY DIFICIL DEFENDERLO."}'),
